import { useCallback, useEffect, useState } from "react";
import { Check, Clock, Play, Plus, Trash2, X } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  DeleteCron,
  ListCrons,
  RunCronNow,
  SaveCron,
  ToggleCron,
} from "../../wailsjs/go/controllers/CronQueue";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

type CronJob = {
  id: string;
  name: string;
  project?: string;
  command: string;
  schedule: string;
  enabled: boolean;
  backgroundMode?: boolean;
  lastRun?: string;
  lastOutput?: string;
};

const PRESETS = [
  { label: "* * * * * (every minute)", value: "* * * * *" },
  { label: "*/5 * * * * (every 5 min)", value: "*/5 * * * *" },
  { label: "0 * * * * (hourly)", value: "0 * * * *" },
  { label: "0 9 * * 1-5 (weekdays 9am)", value: "0 9 * * 1-5" },
  { label: "0 0 * * * (midnight)", value: "0 0 * * *" },
];

export default function Cron() {
  const t = useT();
  const dialogs = useDialogs();
  const [jobs, setJobs] = useState<CronJob[]>([]);
  const [editing, setEditing] = useState<CronJob | null>(null);
  const [showForm, setShowForm] = useState(false);

  const refresh = useCallback(() => {
    ListCrons().then((list: CronJob[]) => setJobs(list ?? [])).catch(() => { /* pre-startup */ });
  }, []);

  useEffect(() => {
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("cron:status", () => refresh());
  }, [refresh]);

  const save = async (job: CronJob) => {
    try {
      await SaveCron(job as any);
      setShowForm(false);
      setEditing(null);
      refresh();
    } catch (error) {
      await dialogs.alert({ title: job.name, message: String(error) });
    }
  };

  const remove = async (job: CronJob) => {
    const yes = await dialogs.confirm({
      title: t("cron.deleteConfirm", { name: job.name }),
      danger: true,
    });
    if (!yes) return;
    await DeleteCron(job.id);
    refresh();
  };

  const runNow = async (job: CronJob) => {
    await RunCronNow(job.id);
  };

  const toggle = async (job: CronJob, enabled: boolean) => {
    await ToggleCron(job.id, enabled);
    refresh();
  };

  return (
    <div className="space-y-4">
      <header className="flex items-center justify-between">
        <h1 className="text-lg font-semibold text-white/95">{t("cron.title")}</h1>
        <button
          type="button"
          onClick={() => {
            setEditing(null);
            setShowForm(true);
          }}
          className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
        >
          <Plus className="h-3.5 w-3.5" /> {t("cron.new")}
        </button>
      </header>

      {showForm && (
        <CronForm
          key={editing?.id ?? "new"}
          job={editing}
          onSave={save}
          onCancel={() => {
            setShowForm(false);
            setEditing(null);
          }}
        />
      )}

      {jobs.length === 0 ? (
        <section className="glass p-8 text-center">
          <p className="text-sm text-white/50">{t("cron.empty")}</p>
        </section>
      ) : (
        <div className="space-y-2">
          {jobs.map((job) => (
            <article key={job.id} className="glass flex items-center gap-3 p-3">
              <button
                type="button"
                onClick={() => void toggle(job, !job.enabled)}
                className={`flex h-5 w-5 shrink-0 items-center justify-center rounded border ${
                  job.enabled
                    ? "border-emerald-400 bg-emerald-400/20 text-emerald-300"
                    : "border-white/20 text-transparent hover:border-white/40"
                }`}
              >
                <Check className="h-3 w-3" />
              </button>
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="truncate text-sm font-medium text-white/90">{job.name}</span>
                  {job.backgroundMode && (
                    <span className="rounded-full border border-accent2/40 px-1.5 py-0.5 text-[9px] text-accent2">
                      {t("cron.background")}
                    </span>
                  )}
                </div>
                <p className="truncate font-mono text-[11px] text-white/40">
                  {job.schedule} · {job.command}
                  {job.project ? ` · ${job.project}` : ""}
                </p>
                {job.lastRun && (
                  <p className="text-[10px] text-white/30">
                    {t("cron.lastRun")}: {new Date(job.lastRun).toLocaleString()}
                  </p>
                )}
              </div>
              <div className="flex shrink-0 items-center gap-1">
                <button
                  type="button"
                  onClick={() => void runNow(job)}
                  title={t("cron.runNow")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Play className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setEditing(job);
                    setShowForm(true);
                  }}
                  title={t("cron.edit")}
                  className="rounded border border-white/10 bg-white/5 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <Clock className="h-3 w-3" />
                </button>
                <button
                  type="button"
                  onClick={() => void remove(job)}
                  title={t("cron.delete")}
                  className="rounded border border-red-400/30 bg-red-500/10 p-1.5 text-red-300 hover:bg-red-500/20"
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}

function CronForm({
  job,
  onSave,
  onCancel,
}: {
  job: CronJob | null;
  onSave: (job: CronJob) => void;
  onCancel: () => void;
}) {
  const t = useT();
  const [name, setName] = useState(job?.name ?? "");
  const [schedule, setSchedule] = useState(job?.schedule ?? "* * * * *");
  const [command, setCommand] = useState(job?.command ?? "");
  const [project, setProject] = useState(job?.project ?? "");
  const [background, setBackground] = useState(job?.backgroundMode ?? false);

  const submit = () => {
    onSave({
      id: job?.id ?? "",
      name, schedule, command, project,
      enabled: job?.enabled ?? true,
      backgroundMode: background,
      lastRun: job?.lastRun ?? "",
      lastOutput: job?.lastOutput ?? "",
    });
  };

  return (
    <section className="glass space-y-3 p-4">
      <div className="grid grid-cols-2 gap-3">
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("cron.name")}</span>
          <input className="input w-full" value={name} onChange={(e) => setName(e.target.value)} />
        </label>
        <label className="space-y-1 text-xs">
          <span className="text-white/60">{t("cron.schedule")}</span>
          <select
            className="input w-full"
            value={PRESETS.some((p) => p.value === schedule) ? schedule : ""}
            onChange={(e) => setSchedule(e.target.value || schedule)}
          >
            <option value="">{schedule}</option>
            {PRESETS.map((p) => (
              <option key={p.value} value={p.value}>{p.label}</option>
            ))}
          </select>
        </label>
      </div>
      <label className="block space-y-1 text-xs">
        <span className="text-white/60">{t("cron.command")}</span>
        <input
          className="input w-full font-mono"
          value={command}
          placeholder="php artisan schedule:run"
          onChange={(e) => setCommand(e.target.value)}
        />
      </label>
      <label className="flex items-center gap-2 text-xs text-white/60">
        <input
          type="checkbox"
          checked={background}
          onChange={(e) => setBackground(e.target.checked)}
          className="h-3.5 w-3.5"
        />
        {t("cron.backgroundHelp")}
      </label>
      <div className="flex justify-end gap-2 pt-2">
        <button type="button" onClick={onCancel} className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/70 hover:bg-white/10">
          {t("dialog.cancel")}
        </button>
        <button
          type="button"
          onClick={submit}
          disabled={!name.trim() || !command.trim() || !schedule.trim()}
          className="rounded-md bg-accent px-4 py-1.5 text-xs font-medium text-white disabled:opacity-40"
        >
          {t("dialog.save")}
        </button>
      </div>
    </section>
  );
}
